256:       log(`<b>Regressão encontrada.</b> Sem instrumentação, o sprint revelou um bug adicional (+1).`);
257:     }
258:     if (state.week === 5 && state.systems.memory === 0) log('<b>Risco de memória sinalizado.</b> O orçamento ainda não tem descarte controlado.');
259:     log(`<b>Sprint ${String(finishedWeek).padStart(2, '0')} fechado.</b> Novo orçamento +${grant} CR; 3 ações restauradas.`);
260:     render();
261:     showToast(`Sprint ${String(finishedWeek).padStart(2, '0')} fechado. +${grant} CR.`);
262:   }
263:   function showEnding() {
264:     const score = health();
265:     let title, text;
266:     if (score >= 72 && state.testRuns >= 2) {
267:       title = 'Bancada validada';
268:       text = `Você construiu uma base de testes consistente, com saúde simulada ${score}/100. Isso valida apenas a disciplina de engenharia e as cargas sintéticas — compatibilidade com qualquer console permanece desconhecida.`;
269:     } else if (score >= 40) {
270:       title = 'Protótipo promissor';
271:       text = `A campanha terminou com saúde ${score}/100. Há fundamentos, mas faltou cobertura ou validação repetida. Nenhum resultado comprova compatibilidade real.`;
272:     } else {
273:       title = 'Viabilidade inconclusiva';
274:       text = `A bancada terminou com saúde ${score}/100. A equipe priorizou trabalho sem fechar validações suficientes; registre riscos e tente outra estratégia. Não há compatibilidade real demonstrada.`;
275:     }
276:     const dialog = $('aboutDialog');
277:     dialog.querySelector('.section-kicker').textContent = 'RESULTADO DA CAMPANHA';
278:     dialog.querySelector('h2').textContent = title;
279:     dialog.querySelector('p').textContent = text;
280:     $('gotItBtn').innerHTML = 'Ver painel <span>✓</span>';
281:     if (!dialog.open) dialog.showModal();
282:   }
283:   function switchView(name) {
284:     const names = { dashboard: 'PAINEL DO PROJETO', roadmap: 'ARQUITETURA & PLANO', bench: 'LABORATÓRIO DE TESTES' };
285:     document.querySelectorAll('.view').forEach(view => view.classList.toggle('active', view.id === `${name}View`));
286:     document.querySelectorAll('.nav-item').forEach(button => button.classList.toggle('active', button.dataset.view === name));
287:     $('crumbTitle').textContent = names[name] || names.dashboard;
288:     $('sidebar').classList.remove('open');
289:     window.scrollTo({ top: 0, behavior: 'smooth' });
290:   }
291:   function reset() {
292:     if (!window.confirm('Reiniciar a campanha? Todo o progresso local será apagado.')) return;
293:     state = freshState();
294:     log('<b>Nova campanha iniciada.</b> Orçamento de 120 CR, seis sprints e três ações por sprint.');
295:     render();
296:     switchView('dashboard');
297:     showToast('Nova campanha pronta.');
298:   }
299:   function init() {
300:     if (!state.logs.length) log('<b>Bancada pronta.</b> Seis sprints disponíveis. Comece pela arquitetura ou invista em um protótipo sintético.');
301:     document.querySelectorAll('.nav-item').forEach(button => button.addEventListener('click', () => switchView(button.dataset.view)));
302:     $('endWeekBtn').addEventListener('click', closeWeek);
303:     $('testButton').addEventListener('click', runTests);
304:     $('benchRunBtn').addEventListener('click', runTests);
305:     $('profileSelect').addEventListener('change', event => { state.profile = event.target.value; log(`<b>Perfil ajustado:</b> ${event.target.options[event.target.selectedIndex].text}. Métricas são apenas estimativas sintéticas.`); render(); });
306:     $('budgetRange').addEventListener('input', event => { state.budget = Number(event.target.value); $('budgetLabel').textContent = state.budget.toFixed(1); renderResources(); save(); });
307:     $('resetBtn').addEventListener('click', reset);
308:     $('dismissNotice').addEventListener('click', () => { state.dismissedNotice = true; render(); });
309:     $('roadmapLink').addEventListener('click', () => switchView('roadmap'));
310:     $('hardwareBtn').addEventListener('click', () => showToast('Máquina-alvo de referência; métricas exibidas são sintéticas, não telemetria real.'));
311:     $('menuBtn').addEventListener('click', () => $('sidebar').classList.toggle('open'));
312:     $('aboutBtn').addEventListener('click', () => $('aboutDialog').showModal());
313:     $('closeAbout').addEventListener('click', () => $('aboutDialog').close());
314:     $('gotItBtn').addEventListener('click', () => $('aboutDialog').close());
315:     $('downloadReport').addEventListener('click', () => {
316:       if (!state.lastTests) return showToast('Execute uma bateria antes de baixar o relatório.');
317:       const blob = new Blob([makeReport()], { type: 'text/plain;charset=utf-8' });
318:       const url = URL.createObjectURL(blob);
319:       const link = document.createElement('a');
320:       link.href = url; link.download = `polaris-lab-relatorio-sprint-${String(state.lastTests.week).padStart(2, '0')}.txt`;
321:       link.click(); URL.revokeObjectURL(url);
322:       showToast('Relatório sintético baixado.');
323:     });
324:     document.addEventListener('keydown', event => { if (event.key === 'Escape') $('sidebar').classList.remove('open'); });
325:     render();
326:   }
